func AllowsRerunWhenFinished(preconditions []apiv1.JobPrecondition) bool {
    for _, precondition := range preconditions {
        if !precondition.RunOnceOrDefault() {
            return true
        }
    }
    return false
}

if matchingJob.Status == jobs.JobStatusFinished {
    rerunFinished := config.Spec.OnUpdate.RerunFinished
    if !isInlineSpec {
        rerunFinished = rerunFinished || config.Spec.OnJobTemplateUpdate.RerunFinished
    }
    if rerunFinished || preconditions.AllowsRerunWhenFinished(jobPreconditions) {
        return true, "rerunning finished job per rerunFinished policy"
    }
    return false, ""
}
